mapper.select:
select prodId, finprodName, serialNo, interType, xmlStatus, checkStatus, valDate, remark, returnTxt from (SELECT BASI.ACCT_SUBJECT_ID prodId, BASI.ACCT_SUBJECT_NAME finprodName, SIV.SERIALNO serialNo, #{INTER_TYPE_VAL,jdbcType=VARCHAR} interType, (case when SIV.XML_STATUS = null then 0 else SIV.XML_STATUS end) xmlStatus, (case when SIV.CHECK_STATUS = then 0 else SIV.CHECK_STATUS end) checkStatus, DATE_FORMAT(BVTD.VAL_DATE, '%Y-%m-%d') valDate, SIV.REMARK remark, SIV.RETURN_TXT returnTxt FROM (SELECT DISTINCT A.BOOKSET_ID, A.VAL_DATE FROM BOK_VAL_TABLE_DATA A)BVTD LEFT JOIN BOK_BOOKSET BB ON BVTD.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON BB.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = BB.ACCT_SUBJECT_TYPE LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = BB.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = #{INTER_TYPE_VAL,jdbcType=VARCHAR} AND SIV.CDATE = DATE_FORMAT(BVTD.VAL_DATE, '%Y-%m-%d')) where 1 = 1
AND prodId IN
#{item}
and valDate = DATE_FORMAT(STR_TO_DATE(#{valDate,jdbcType=DATE},'%Y-%m-%d'),'%Y-%m-%d') and xmlStatus = #{xmlStatus,jdbcType=VARCHAR} and checkStatus = #{checkStatus,jdbcType=VARCHAR} and #{INTER_TYPE_VAL,jdbcType=VARCHAR} = #{interType,jdbcType=VARCHAR} union select prodId, finprodName, serialNo, interType, xmlStatus, checkStatus, valDate, remark, returnTxt from (SELECT BASI.ACCT_SUBJECT_ID prodId, BASI.ACCT_SUBJECT_NAME finprodName, SIV.SERIALNO serialNo, #{INTER_TYPE_BALANCEL,jdbcType=VARCHAR} interType, (case when SIV.XML_STATUS = null then 0 else SIV.XML_STATUS end) xmlStatus, (case when SIV.CHECK_STATUS = null then 0 else SIV.CHECK_STATUS end) checkStatus, DATE_FORMAT(B.BALANCE_DATE, '%Y-%m-%d') valDate, SIV.REMARK remark, SIV.RETURN_TXT returnTxt FROM (SELECT DISTINCT A.BOOKSET_ID, A.BALANCE_DATE FROM BOK_BALANCE A)B LEFT JOIN BOK_BOOKSET BB ON B.BOOKSET_ID = BB.BOOKSET_ID LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON BB.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = BB.ACCT_SUBJECT_TYPE LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = BB.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = #{INTER_TYPE_BALANCEL,jdbcType=VARCHAR} AND SIV.CDATE = DATE_FORMAT(B.BALANCE_DATE, '%Y-%m-%d')) where 1 = 1
AND prodId IN
#{item}
and valDate = DATE_FORMAT(STR_TO_DATE(#{valDate,jdbcType=DATE},'%Y-%m-%d'),'%Y-%m-%d') and xmlStatus = #{xmlStatus,jdbcType=VARCHAR} and checkStatus = #{checkStatus,jdbcType=VARCHAR} and #{INTER_TYPE_BALANCEL,jdbcType=VARCHAR} = #{interType,jdbcType=VARCHAR}
